function Get-Windows {
 $items=New-Object System.Collections.Generic.List[object]
 $cb=[JessWin32+EnumWindowsProc]{param([IntPtr]$h,[IntPtr]$lp)
  if(-not [JessWin32]::IsWindowVisible($h)){return $true}
  $sb=New-Object System.Text.StringBuilder 1024;[void][JessWin32]::GetWindowText($h,$sb,$sb.Capacity);$title=$sb.ToString().Trim();if(!$title){return $true}
  $processId=[uint32]0;[void][JessWin32]::GetWindowThreadProcessId($h,[ref]$processId);$r=New-Object JessWin32+RECT;[void][JessWin32]::GetWindowRect($h,[ref]$r);$proc='';try{$proc=(Get-Process -Id $processId -ErrorAction Stop).ProcessName}catch{}
  $monitor=$null;try{$scr=[System.Windows.Forms.Screen]::FromHandle($h);$all=[System.Windows.Forms.Screen]::AllScreens;$monitorIndex=[Array]::IndexOf($all,$scr)+1;$monitor=@{index=$monitorIndex;deviceName=$scr.DeviceName;primary=$scr.Primary;bounds=@{x=$scr.Bounds.X;y=$scr.Bounds.Y;width=$scr.Bounds.Width;height=$scr.Bounds.Height};workingArea=@{x=$scr.WorkingArea.X;y=$scr.WorkingArea.Y;width=$scr.WorkingArea.Width;height=$scr.WorkingArea.Height}}}catch{}
  $items.Add([pscustomobject]@{handle=$h.ToInt64();title=$title;process=$proc;pid=$processId;bounds=@{x=$r.Left;y=$r.Top;width=$r.Right-$r.Left;height=$r.Bottom-$r.Top};monitor=$monitor;state=$(if([JessWin32]::IsIconic($h)){'minimized'}elseif([JessWin32]::IsZoomed($h)){'maximized'}else{'normal'});foreground=($h -eq [JessWin32]::GetForegroundWindow())});return $true
 }
 [void][JessWin32]::EnumWindows($cb,[IntPtr]::Zero);return @($items)
}
function Find-Window($a){
 $ws=Get-Windows
 if($null -ne $a.handle -and [string]$a.handle -ne ''){
  $handleMatches=@($ws|Where-Object{[string]$_.handle -eq [string]$a.handle})
  if($handleMatches.Count -eq 1){return $handleMatches[0]}
  return $null
 }
 if($a.title){
  $needle=[string]$a.title
  $exact=@($ws|Where-Object{[string]::Equals([string]$_.title,$needle,[StringComparison]::OrdinalIgnoreCase)})
  if($exact.Count -eq 1){return $exact[0]}
  if($exact.Count -gt 1){throw 'Window title is ambiguous; provide the exact window handle.'}
  $titleMatches=@($ws|Where-Object{$_.title.IndexOf($needle,[StringComparison]::OrdinalIgnoreCase) -ge 0})
  if($titleMatches.Count -eq 1){return $titleMatches[0]}
  if($titleMatches.Count -gt 1){throw 'Window title is ambiguous; provide the exact window handle.'}
 }
 return $null
}
function Get-FocusedUiState {
 $focused=$null;$windowHandle=[JessWin32]::GetForegroundWindow().ToInt64();$name='';$automationId='';$value='';$controlType='';$bounds=$null
 try{
  $focused=[System.Windows.Automation.AutomationElement]::FocusedElement
  if($focused){
   $name=[string]$focused.Current.Name;$automationId=[string]$focused.Current.AutomationId;$controlType=[string]$focused.Current.ControlType.ProgrammaticName
   $rect=$focused.Current.BoundingRectangle;$bounds=@{x=[int]$rect.X;y=[int]$rect.Y;width=[int]$rect.Width;height=[int]$rect.Height}
   $pattern=$null
   if($focused.TryGetCurrentPattern([System.Windows.Automation.ValuePattern]::Pattern,[ref]$pattern)){$value=[string]$pattern.Current.Value}
   else{$pattern=$null;if($focused.TryGetCurrentPattern([System.Windows.Automation.TextPattern]::Pattern,[ref]$pattern)){$value=[string]$pattern.DocumentRange.GetText(10000)}}
  }
 }catch{}
 return @{windowHandle=$windowHandle;name=$name;automationId=$automationId;controlType=$controlType;value=$value;bounds=$bounds}
}
function Get-ForegroundUiSnapshot {
 $h=[JessWin32]::GetForegroundWindow();if($h -eq [IntPtr]::Zero){return ''}
 $lines=New-Object System.Collections.Generic.List[string]
 try{
  $root=[System.Windows.Automation.AutomationElement]::FromHandle($h)
  $cond=New-Object System.Windows.Automation.PropertyCondition([System.Windows.Automation.AutomationElement]::IsControlElementProperty,$true)
  $all=$root.FindAll([System.Windows.Automation.TreeScope]::Descendants,$cond)
  for($i=0;$i -lt [Math]::Min($all.Count,600);$i++){
   try{
    $el=$all.Item($i);$name=[string]$el.Current.Name
    if($name){$lines.Add($name)}
    $pattern=$null
    if($el.TryGetCurrentPattern([System.Windows.Automation.ValuePattern]::Pattern,[ref]$pattern)){$val=[string]$pattern.Current.Value;if($val){$lines.Add('VALUE:'+ $val.Substring(0,[Math]::Min(500,$val.Length)))}}
    $pattern=$null
    if($el.TryGetCurrentPattern([System.Windows.Automation.ScrollPattern]::Pattern,[ref]$pattern)){$scroll=$pattern.Current;$lines.Add('SCROLL:'+ [string]$scroll.VerticalScrollPercent+':'+[string]$scroll.HorizontalScrollPercent)}
   }catch{}
  }
 }catch{}
 return ($lines -join [Environment]::NewLine).Substring(0,[Math]::Min(12000,($lines -join [Environment]::NewLine).Length))
}
function Resolve-UserFilePath($requested,$mustExist=$false){
 if($null -eq $requested -or [string]$requested -eq '' -or ([string]$requested).Length -gt 2048 -or ([string]$requested).Contains([char]0)){throw 'Provide a valid user-file path'}
 $full=[System.IO.Path]::GetFullPath([string]$requested)
 $roots=@([Environment]::GetFolderPath([Environment+SpecialFolder]::DesktopDirectory),[Environment]::GetFolderPath([Environment+SpecialFolder]::MyDocuments),(Join-Path $env:USERPROFILE 'Downloads'),$env:OneDrive)|Where-Object{$_ -and (Test-Path -LiteralPath $_ -PathType Container)}
 $allowed=$false
 foreach($root in $roots){$base=[System.IO.Path]::GetFullPath([string]$root).TrimEnd('\');if($full.Equals($base,[StringComparison]::OrdinalIgnoreCase)-or $full.StartsWith($base+'\',[StringComparison]::OrdinalIgnoreCase)){$allowed=$true;break}}
 if(!$allowed){throw 'File tools are limited to the current user Desktop, Documents, Downloads and OneDrive folders'}
 if($mustExist -and !(Test-Path -LiteralPath $full)){throw 'The requested file or folder does not exist'}
 return $full
}
function Send-Key($key,$holdMs=35){
 $map=@{ENTER=13;ESC=27;TAB=9;SPACE=32;BACKSPACE=8;DELETE=46;INSERT=45;PRTSC=44;PRINTSCREEN=44;CAPSLOCK=20;PAGEUP=33;PAGEDOWN=34;UP=38;DOWN=40;LEFT=37;RIGHT=39;HOME=36;END=35;CTRL=17;ALT=18;SHIFT=16;WIN=91;F1=112;F2=113;F3=114;F4=115;F5=116;F6=117;F7=118;F8=119;F9=120;F10=121;F11=122;F12=123;F13=124;F14=125;F15=126;F16=127;F17=128;F18=129;F19=130;F20=131;F21=132;F22=133;F23=134;F24=135;VOLUME_MUTE=173;VOLUME_DOWN=174;VOLUME_UP=175;MEDIA_NEXT=176;MEDIA_PREV=177;MEDIA_STOP=178;MEDIA_PLAY_PAUSE=179;BROWSER_BACK=166;BROWSER_FORWARD=167}
 $extended=@{DELETE=$true;INSERT=$true;PRTSC=$true;PRINTSCREEN=$true;PAGEUP=$true;PAGEDOWN=$true;UP=$true;DOWN=$true;LEFT=$true;RIGHT=$true;HOME=$true;END=$true;WIN=$true;VOLUME_MUTE=$true;VOLUME_DOWN=$true;VOLUME_UP=$true;MEDIA_NEXT=$true;MEDIA_PREV=$true;MEDIA_STOP=$true;MEDIA_PLAY_PAUSE=$true;BROWSER_BACK=$true;BROWSER_FORWARD=$true}
 $parts=$key.ToUpperInvariant().Split('+');$down=New-Object System.Collections.Generic.List[JessWin32+INPUT]
 foreach($p in $parts){$v=$map[$p];if($null -eq $v -and $p.Length -eq 1){$v=[int][char]$p};if($null -eq $v -or [int]$v -eq 0){throw ('Unsupported key '+$p)};$flags=0;if($extended.ContainsKey($p) -and $extended[$p]){$flags=[JessWin32]::EXTENDED};$down.Add([JessWin32]::KeyboardInput([uint16]$v,0,[uint32]$flags))}
 $downArray=$down.ToArray();$sent=[JessWin32]::SendInput([uint32]$downArray.Length,$downArray,[Runtime.InteropServices.Marshal]::SizeOf([type][JessWin32+INPUT]))
 if($sent -ne $downArray.Length){throw 'Windows did not accept every key-down event'}
 Start-Sleep -Milliseconds ([Math]::Max(0,[Math]::Min(5000,[int]$holdMs)))
 $up=New-Object System.Collections.Generic.List[JessWin32+INPUT]
 for($n=$parts.Length-1;$n -ge 0;$n--){$p=$parts[$n];$v=$map[$p];if($null -eq $v -and $p.Length -eq 1){$v=[int][char]$p};$flags=[JessWin32]::KEYUP;if($extended.ContainsKey($p) -and $extended[$p]){$flags=$flags -bor [JessWin32]::EXTENDED};$up.Add([JessWin32]::KeyboardInput([uint16]$v,0,[uint32]$flags))}
 $upArray=$up.ToArray();$sent=[JessWin32]::SendInput([uint32]$upArray.Length,$upArray,[Runtime.InteropServices.Marshal]::SizeOf([type][JessWin32+INPUT]))
 if($sent -ne $upArray.Length){throw 'Windows did not accept every key-up event'}
 Start-Sleep -Milliseconds 20
}
function Invoke-Action($q){
 $a=$q.args
 switch($q.method){
 'list_windows' {return @{ok=$true;verified=$true;evidence=(Get-Windows)}}
 'bring_to_front' {$w=Find-Window $a;if(!$w){throw 'Window not found'};$h=[IntPtr]$w.handle;[void][JessWin32]::ShowWindowAsync($h,9);[void][JessWin32]::BringWindowToTop($h);[void][JessWin32]::SetForegroundWindow($h);Start-Sleep -Milliseconds 180;$foreground=[JessWin32]::GetForegroundWindow().ToInt64();$ok=($foreground -eq [int64]$w.handle);return @{ok=$ok;verified=$ok;evidence=@{window=$w;foreground=$foreground}}}
 'send_to_back' {$w=Find-Window $a;if(!$w){throw 'Window not found'};$h=[IntPtr]$w.handle;$flags=[JessWin32]::SWP_NOMOVE -bor [JessWin32]::SWP_NOSIZE -bor [JessWin32]::SWP_NOACTIVATE;$sent=[JessWin32]::SetWindowPos($h,[IntPtr]1,0,0,0,0,[uint32]$flags);Start-Sleep -Milliseconds 120;return @{ok=$sent;verified=$false;evidence=@{window=$w;note='Window was sent to the bottom of the z-order; exact z-order is not independently verified'}}}
 'click_window_point' {$w=Find-Window $a;if(!$w){throw 'Window not found'};$nx=[double]$a.x;$ny=[double]$a.y;if($nx -lt 0 -or $nx -gt 1 -or $ny -lt 0 -or $ny -gt 1){throw 'Window-relative coordinates must be normalized between 0 and 1'};$x=[int]([double]$w.bounds.x+[Math]::Round([double]$w.bounds.width*$nx));$y=[int]([double]$w.bounds.y+[Math]::Round([double]$w.bounds.height*$ny));$h=[IntPtr]$w.handle;[void][JessWin32]::ShowWindowAsync($h,9);[void][JessWin32]::BringWindowToTop($h);[void][JessWin32]::SetForegroundWindow($h);Start-Sleep -Milliseconds 100;[void][JessWin32]::SetCursorPos($x,$y);[JessWin32]::mouse_event(2,0,0,0,[UIntPtr]::Zero);Start-Sleep -Milliseconds 50;[JessWin32]::mouse_event(4,0,0,0,[UIntPtr]::Zero);return @{ok=$true;verified=$false;evidence=@{window=$w;normalized=@{x=$nx;y=$ny};screen=@{x=$x;y=$y};note='Window-relative point mapped through the current window rectangle; click delivery does not prove the target control activated'}}}
 'focus_window' {$w=Find-Window $a;if(!$w){throw 'Window not found'};[void][JessWin32]::ShowWindowAsync([IntPtr]$w.handle,9);[void][JessWin32]::BringWindowToTop([IntPtr]$w.handle);[void][JessWin32]::SetForegroundWindow([IntPtr]$w.handle);Start-Sleep -Milliseconds 250;$ok=([JessWin32]::GetForegroundWindow().ToInt64() -eq [int64]$w.handle);return @{ok=$ok;verified=$ok;evidence=@{window=$w;foreground=([JessWin32]::GetForegroundWindow().ToInt64())}}}
 {$_ -in 'close_window','minimize_window','maximize_window','restore_window','move_window','resize_window','snap_window','move_to_monitor'} {$w=Find-Window $a;if(!$w){throw 'Window not found'};$h=[IntPtr]$w.handle;switch($q.method){'close_window'{[void][JessWin32]::PostMessage($h,0x0010,[IntPtr]::Zero,[IntPtr]::Zero);Start-Sleep -Milliseconds 300;$exists=[JessWin32]::IsWindow($h);return @{ok=(-not $exists);verified=(-not $exists);evidence=@{window=$w;windowHandleStillExists=$exists}}}'minimize_window'{[void][JessWin32]::ShowWindowAsync($h,6)}'maximize_window'{[void][JessWin32]::ShowWindowAsync($h,3)}'restore_window'{[void][JessWin32]::ShowWindowAsync($h,9)}default{$r=$w.bounds;$x=[int]$r.x;$y=[int]$r.y;$ww=[int]$r.width;$hh=[int]$r.height;if($q.method -eq 'move_window'){$x=[int]$a.x;$y=[int]$a.y};if($q.method -eq 'resize_window'){$ww=[Math]::Max(200,[int]$a.width);$hh=[Math]::Max(150,[int]$a.height)};if($q.method -eq 'snap_window'){
 $screens=[System.Windows.Forms.Screen]::AllScreens
 if($null -ne $a.monitor){$monitorIndex=[int]$a.monitor;if($monitorIndex -lt 1 -or $monitorIndex -gt $screens.Length){throw 'Monitor index must identify a connected display starting at 1'};$targetScreen=$screens[$monitorIndex-1]}else{$targetScreen=[System.Windows.Forms.Screen]::FromHandle($h)}
 $area=$targetScreen.WorkingArea;$halfW=[int][Math]::Floor($area.Width/2);$halfH=[int][Math]::Floor($area.Height/2);$thirdW=[int][Math]::Floor($area.Width/3);$thirdH=[int][Math]::Floor($area.Height/3)
 switch([string]$a.position){
 'left'{$x=$area.X;$y=$area.Y;$ww=$halfW;$hh=$area.Height}
 'right'{$x=$area.X+$halfW;$y=$area.Y;$ww=$area.Width-$halfW;$hh=$area.Height}
 'top-right'{$x=$area.X+$halfW;$y=$area.Y;$ww=$area.Width-$halfW;$hh=$halfH}
 'top-left'{$x=$area.X;$y=$area.Y;$ww=$halfW;$hh=$halfH}
 'bottom-right'{$x=$area.X+$halfW;$y=$area.Y+$halfH;$ww=$area.Width-$halfW;$hh=$area.Height-$halfH}
 'bottom-left'{$x=$area.X;$y=$area.Y+$halfH;$ww=$halfW;$hh=$area.Height-$halfH}
 'left-third'{$x=$area.X;$y=$area.Y;$ww=$thirdW;$hh=$area.Height}
