 'bottom-third'{$x=$area.X;$y=$area.Y+2*$thirdH;$ww=$area.Width;$hh=$area.Height-2*$thirdH}
 'top-left-third'{$x=$area.X;$y=$area.Y;$ww=$thirdW;$hh=$thirdH}
 'top-right-third'{$x=$area.X+2*$thirdW;$y=$area.Y;$ww=$area.Width-2*$thirdW;$hh=$thirdH}
 'bottom-left-third'{$x=$area.X;$y=$area.Y+2*$thirdH;$ww=$thirdW;$hh=$area.Height-2*$thirdH}
 'bottom-right-third'{$x=$area.X+2*$thirdW;$y=$area.Y+2*$thirdH;$ww=$area.Width-2*$thirdW;$hh=$area.Height-2*$thirdH}
 default{throw 'Unsupported snap position'}
 }
}
if($q.method -eq 'move_to_monitor'){
 $screens=[System.Windows.Forms.Screen]::AllScreens;$monitorIndex=[int]$a.monitor;if($monitorIndex -lt 1 -or $monitorIndex -gt $screens.Length){throw 'Monitor index must identify a connected display starting at 1'};$area=$screens[$monitorIndex-1].WorkingArea;$x=$area.X+[int][Math]::Max(0,[Math]::Min($area.Width-$ww,$x-$w.bounds.x));$y=$area.Y+[int][Math]::Max(0,[Math]::Min($area.Height-$hh,$y-$w.bounds.y))
}[void][JessWin32]::ShowWindowAsync($h,9);if(-not [JessWin32]::MoveWindow($h,$x,$y,$ww,$hh,$true)){throw 'MoveWindow failed'}}};Start-Sleep -Milliseconds 180;$after=Find-Window @{handle=$w.handle};$verified=$false;if($after){switch($q.method){'minimize_window'{$verified=$after.state -eq 'minimized'}'maximize_window'{$verified=$after.state -eq 'maximized'}'restore_window'{$verified=$after.state -ne 'minimized'}'move_window'{$verified=([Math]::Abs([int]$after.bounds.x-[int]$a.x) -le 4 -and [Math]::Abs([int]$after.bounds.y-[int]$a.y) -le 4)}'resize_window'{$verified=([Math]::Abs([int]$after.bounds.width-[int]$a.width) -le 12 -and [Math]::Abs([int]$after.bounds.height-[int]$a.height) -le 12)}'snap_window'{$verified=([Math]::Abs([int]$after.bounds.width-[int]$ww) -le 12 -and [Math]::Abs([int]$after.bounds.height-[int]$hh) -le 12)}'move_to_monitor'{$verified=([int]$after.monitor.index -eq [int]$a.monitor)}}};return @{ok=$verified;verified=$verified;evidence=@{before=$w;after=$after;expected=@{x=$x;y=$y;width=$ww;height=$hh}}}}
 'mouse_move' {$sent=[JessWin32]::SetCursorPos([int]$a.x,[int]$a.y);Start-Sleep -Milliseconds 25;$p=New-Object JessWin32+POINT;$read=[JessWin32]::GetCursorPos([ref]$p);$ok=($sent -and $read -and $p.X -eq [int]$a.x -and $p.Y -eq [int]$a.y);return @{ok=$sent;verified=$ok;evidence=@{requested=@{x=$a.x;y=$a.y};readback=@{x=$p.X;y=$p.Y};readbackMatches=$ok}}}
 {$_ -in 'click','double_click','right_click'} {$beforeForeground=[JessWin32]::GetForegroundWindow().ToInt64();$beforeSnapshot=Get-ForegroundUiSnapshot;[void][JessWin32]::SetCursorPos([int]$a.x,[int]$a.y);$down=2;$up=4;if($q.method -eq 'right_click'){$down=8;$up=16};$count=1;if($q.method -eq 'double_click'){$count=2};1..$count|ForEach-Object{[JessWin32]::mouse_event($down,0,0,0,[UIntPtr]::Zero);[JessWin32]::mouse_event($up,0,0,0,[UIntPtr]::Zero);Start-Sleep -Milliseconds 70};Start-Sleep -Milliseconds 180;$afterForeground=[JessWin32]::GetForegroundWindow().ToInt64();$afterSnapshot=Get-ForegroundUiSnapshot;$snapshotChanged=($beforeSnapshot -ne $afterSnapshot);$foregroundChanged=($beforeForeground -ne $afterForeground);$verified=$snapshotChanged -or $foregroundChanged;return @{ok=$true;verified=$verified;evidence=@{x=$a.x;y=$a.y;beforeForeground=$beforeForeground;afterForeground=$afterForeground;snapshotChanged=$snapshotChanged;note=$(if($verified){'UI Automation state or foreground window changed after the click'}else{'Click event was sent, but no independent UI postcondition change was observed'})}}}
 'scroll' {$delta=[int]$a.delta;if($delta -lt -12000 -or $delta -gt 12000){throw 'Scroll delta must be between -12000 and 12000'};[void][JessWin32]::SetCursorPos([int]$a.x,[int]$a.y);$horizontal=([string]$a.axis -eq 'horizontal');$bits=[JessWin32]::SendWheel($delta,$horizontal);Start-Sleep -Milliseconds 100;return @{ok=$true;verified=$false;evidence=@{x=$a.x;y=$a.y;delta=$delta;axis=$(if($horizontal){'horizontal'}else{'vertical'});unsignedWheelData=$bits}}}
